"""Aturan permainan. Tidak ada input(), print(), atau random di sini."""

LEVEL = {
    "mudah": {"bawah": 1, "atas": 20, "kesempatan": 6, "pengali": 1},
    "sedang": {"bawah": 1, "atas": 50, "kesempatan": 7, "pengali": 2},
    "sulit": {"bawah": 1, "atas": 100, "kesempatan": 7, "pengali": 3},
}


def baca_tebakan(teks: str, bawah: int, atas: int) -> int:
    """Ubah ketikan pemain menjadi angka, atau lempar ValueError berisi pesan ramah."""
    teks = teks.strip()
    if not teks:
        raise ValueError("Ketik sebuah angka dulu, ya.")
    try:
        angka = int(teks)
    except ValueError:
        raise ValueError(f"'{teks}' bukan angka bulat.") from None
    if not bawah <= angka <= atas:
        raise ValueError(f"Angkanya harus di antara {bawah} dan {atas}.")
    return angka


def suhu(tebakan: int, rahasia: int, bawah: int, atas: int) -> str:
    """Seberapa dekat tebakan, relatif terhadap lebar rentang."""
    jarak = abs(tebakan - rahasia)
    rentang = atas - bawah + 1
    if jarak <= max(1, rentang // 20):
        return "panas"
    if jarak <= rentang // 5:
        return "hangat"
    return "dingin"


def petunjuk(tebakan: int, rahasia: int, bawah: int, atas: int) -> str:
    if tebakan == rahasia:
        return "Benar!"
    arah = "Terlalu kecil" if tebakan < rahasia else "Terlalu besar"
    return f"{arah}, {suhu(tebakan, rahasia, bawah, atas)}."


def hitung_skor(nama_level: str, dipakai: int) -> int:
    """Makin sedikit tebakan, makin besar skornya. Level sulit dikali 3."""
    level = LEVEL[nama_level]
    return (level["kesempatan"] - dipakai + 1) * 10 * level["pengali"]

"""Simpan dan baca skor terbaik per level di berkas JSON."""

import json
from pathlib import Path


def muat_rekor(berkas: Path) -> dict[str, int]:
    """Berkas belum ada, rusak, atau isinya aneh: mulai dari nol, jangan crash."""
    try:
        data = json.loads(berkas.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    return {
        nama: skor
        for nama, skor in data.items()
        if isinstance(skor, int) and not isinstance(skor, bool)
    }


def simpan_rekor(berkas: Path, rekor: dict[str, int]) -> None:
    """Tulis ke berkas sementara dulu, lalu ganti sekaligus.

    Kalau program terhenti di tengah penulisan, berkas lama tetap utuh.
    """
    sementara = berkas.with_name(berkas.name + ".tmp")
    sementara.write_text(json.dumps(rekor, indent=2), encoding="utf-8")
    sementara.replace(berkas)

import pytest

from tebak_angka.logika import baca_tebakan, hitung_skor, petunjuk, suhu


@pytest.mark.parametrize("teks, hasil", [("7", 7), ("  20 ", 20), ("1", 1)])
def test_baca_tebakan_valid(teks, hasil):
    assert baca_tebakan(teks, 1, 20) == hasil


@pytest.mark.parametrize(
    "teks, pesan",
    [
        ("", "Ketik sebuah angka"),
        ("   ", "Ketik sebuah angka"),
        ("abc", "bukan angka bulat"),
        ("7.5", "bukan angka bulat"),
        ("0", "di antara 1 dan 20"),
        ("21", "di antara 1 dan 20"),
    ],
)
def test_baca_tebakan_tidak_valid(teks, pesan):
    with pytest.raises(ValueError, match=pesan):
        baca_tebakan(teks, 1, 20)


@pytest.mark.parametrize(
    "tebakan, hasil",
    [(45, "panas"), (55, "panas"), (44, "hangat"), (30, "hangat"), (29, "dingin"), (100, "dingin")],
)
def test_suhu_rentang_1_sampai_100(tebakan, hasil):
    assert suhu(tebakan, 50, 1, 100) == hasil


def test_petunjuk_menyebut_arah_dan_suhu():
    assert petunjuk(10, 50, 1, 100) == "Terlalu kecil, dingin."
    assert petunjuk(53, 50, 1, 100) == "Terlalu besar, panas."
    assert petunjuk(50, 50, 1, 100) == "Benar!"


def test_skor_makin_besar_kalau_makin_cepat():
    assert hitung_skor("mudah", 1) == 60
    assert hitung_skor("mudah", 6) == 10
    assert hitung_skor("sulit", 7) == 30

import json

from tebak_angka.rekor import muat_rekor, simpan_rekor


def test_berkas_belum_ada(tmp_path):
    assert muat_rekor(tmp_path / "tidak-ada.json") == {}


def test_berkas_rusak(tmp_path):
    berkas = tmp_path / "rekor.json"
    berkas.write_text("{ini bukan json", encoding="utf-8")
    assert muat_rekor(berkas) == {}


def test_isi_bukan_objek_atau_nilai_aneh(tmp_path):
    berkas = tmp_path / "rekor.json"
    berkas.write_text("[1, 2, 3]", encoding="utf-8")
    assert muat_rekor(berkas) == {}
    berkas.write_text('{"mudah": 50, "sedang": "banyak", "sulit": true}', encoding="utf-8")
    assert muat_rekor(berkas) == {"mudah": 50}


def test_simpan_lalu_muat(tmp_path):
    berkas = tmp_path / "rekor.json"
    simpan_rekor(berkas, {"sulit": 120})
    assert muat_rekor(berkas) == {"sulit": 120}
    assert json.loads(berkas.read_text(encoding="utf-8")) == {"sulit": 120}
    assert list(tmp_path.iterdir()) == [berkas]  # berkas .tmp sudah hilang

import json
import random

from tebak_angka import main


def jawaban(*isi):
    """Pengganti input(): mengembalikan isi satu per satu, lalu EOFError seperti Ctrl+D."""
    antrean = iter(isi)

    def tanya(prompt=""):
        try:
            return next(antrean)
        except StopIteration:
            raise EOFError from None

    return tanya


class AcakTetap:
    """Pengganti random.Random() yang selalu memilih angka yang kita tentukan."""

    def __init__(self, *angka):
        self.angka = list(angka)

    def randint(self, bawah, atas):
        return self.angka.pop(0)


def main_palsu(tmp_path, *isi, acak):
    keluar = []
    kode = main(tanya=jawaban(*isi), tulis=keluar.append, acak=acak, berkas=tmp_path / "rekor.json")
    return kode, "\n".join(keluar)


def test_menang_dan_rekor_tersimpan(tmp_path):
    kode, layar = main_palsu(tmp_path, "1", "12", "15", "n", acak=AcakTetap(15))
    assert kode == 0
    assert "Terlalu kecil, hangat." in layar
    assert "ketemu dalam 2 tebakan. Skor: 50" in layar
    assert "Rekor baru untuk level mudah!" in layar
    assert json.loads((tmp_path / "rekor.json").read_text(encoding="utf-8")) == {"mudah": 50}


def test_input_salah_tidak_mengurangi_kesempatan(tmp_path):
    _, layar = main_palsu(tmp_path, "1", "", "abc", "0", "21", "15", "n", acak=AcakTetap(15))
    assert "Ketik sebuah angka dulu, ya." in layar
    assert "'abc' bukan angka bulat." in layar
    assert "Angkanya harus di antara 1 dan 20." in layar
    assert "ketemu dalam 1 tebakan" in layar


def test_tebakan_yang_sama_tidak_dihitung(tmp_path):
    _, layar = main_palsu(tmp_path, "1", "4", "4", "15", "n", acak=AcakTetap(15))
    assert "Kamu sudah menebak 4." in layar
    assert "ketemu dalam 2 tebakan" in layar


def test_kalah_kalau_kesempatan_habis(tmp_path):
    _, layar = main_palsu(tmp_path, "1", "1", "2", "3", "4", "5", "6", "n", acak=AcakTetap(20))
    assert "Kesempatan habis. Angkanya 20." in layar
    assert not (tmp_path / "rekor.json").exists()


def test_main_lagi_dan_rekor_tidak_turun(tmp_path):
    (tmp_path / "rekor.json").write_text('{"mudah": 60}', encoding="utf-8")
    _, layar = main_palsu(tmp_path, "1", "3", "y", "sulit", "50", "n", acak=AcakTetap(3, 50))
    assert "Skor terbaik level mudah: 60" in layar
    assert "Rekor baru untuk level sulit!" in layar
    rekor = json.loads((tmp_path / "rekor.json").read_text(encoding="utf-8"))
    assert rekor == {"mudah": 60, "sulit": 210}


def test_berkas_rekor_rusak_tidak_membuat_crash(tmp_path):
    (tmp_path / "rekor.json").write_text("{rusak", encoding="utf-8")
    kode, _ = main_palsu(tmp_path, "1", "15", "n", acak=AcakTetap(15))
    assert kode == 0
    assert json.loads((tmp_path / "rekor.json").read_text(encoding="utf-8")) == {"mudah": 60}


def test_ctrl_d_di_tengah_ronde_keluar_dengan_rapi(tmp_path):
    kode, layar = main_palsu(tmp_path, "1", "5", acak=AcakTetap(15))
    assert kode == 0
    assert layar.endswith("Sampai jumpa!")


def test_ctrl_c_keluar_dengan_rapi(tmp_path):
    def tanya(prompt=""):
        raise KeyboardInterrupt

    keluar = []
    assert main(tanya=tanya, tulis=keluar.append, berkas=tmp_path / "rekor.json") == 0
    assert keluar[-1] == "Sampai jumpa!"


def test_random_dengan_seed_selalu_sama(tmp_path):
    rahasia = random.Random(2026).randint(1, 20)
    _, layar = main_palsu(tmp_path, "1", str(rahasia), "n", acak=random.Random(2026))
    assert f"Benar! Angkanya {rahasia}, ketemu dalam 1 tebakan." in layar
